"""Verify immutable radar delivery and compare rain-only candidate profiles."""
from pathlib import Path
import sys,os,json,datetime as dt
os.environ.setdefault('MPLCONFIGDIR','/private/tmp/udt-population-mpl');os.environ.setdefault('OPENBLAS_NUM_THREADS','1')
import numpy as np,pandas as pd
from scipy.sparse import load_npz
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'src/preprocessing'));from acquire_tokyo_historical_radar_v1 import decode,sha
P=ROOT/'data/processed/three_ward_population_additional_radar_v1';R=ROOT/'data/exp/data-preprocessing/three_ward_population_additional_radar_v1'
def dump(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2,default=lambda z:z.item()if isinstance(z,np.generic)else str(z),allow_nan=False)+'\n')
def main():
 inv=json.loads((P/'event_inventory.json').read_text());mat=load_npz(ROOT/'data/processed/tokyo_historical_radar_20240821_v1/terrain_source_area_matrix.npz');areas=np.asarray(mat.sum(0)).ravel();used=areas>0;checks={};new=[]
 for event in inv['events']:
  ep=P/event['event_id'];manifest=json.loads((ep/'acquisition_manifest.json').read_text());sur=np.load(ep/'survey_radar_intervals.npz');sel=np.load(ep/'radar_intervals.npz');rate=sur['representative_intensity_mm_h'];end=sur['interval_end_unix_s'];start=sur['interval_start_unix_s'];prefix=event['event_id'];avg=rate.reshape(288,-1)[:,used].astype(float)@areas[used]/areas.sum();rolling=np.convolve(avg/12,np.ones(108),'valid');i=int(np.argmax(rolling));j=event['window_start_index'];checks[prefix+'_continuous']=bool(np.all(end-start==300)and np.array_equal(end[:-1],start[1:]));checks[prefix+'_window_selection']=i==j and np.array_equal(sel['representative_intensity_mm_h'],rate[j:j+108]);checks[prefix+'_rain_integral']=abs(float(rolling[i])-event['reconstructed_rain_mm'])<1e-8;checks[prefix+'_no_missing_or_saturation']=bool(np.isfinite(rate.reshape(288,-1)[:,used]).all()and not(sur['level'].reshape(288,-1)[:,used]==251).any());checks[prefix+'_sha256']=all(sha((ROOT/f['path']).read_bytes())==f['sha256']for f in manifest['files']+manifest['documents']);checks[prefix+'_unique_frames']=len({f['url']for f in manifest['files']})==288
  for k in [0,j,j+107,287]:
   level,r,meta=decode((ROOT/manifest['files'][k]['path']).read_bytes());assert np.array_equal(level,sur['level'][k])and np.array_equal(r,rate[k],equal_nan=True);assert dt.datetime.fromisoformat(meta['utc']).timestamp()==end[k]
  new.append(dict(event_id=prefix,role='new_rain_input_only',window_start_jst=event['window_start_jst'],nine_hour_mm=event['reconstructed_rain_mm'],max_rolling_hour_mm=event['peak_rolling60min_reconstructed_mm'],chiyoda_mm=event['ward_mean_reconstructed_mm']['1'],chuo_mm=event['ward_mean_reconstructed_mm']['2'],minato_mm=event['ward_mean_reconstructed_mm']['3'],prior_rain_outside_window_mm=event['rain_before_window_mm'],hydraulic_result_available=False))
 old=json.loads((ROOT/'data/processed/three_ward_cross_event_protection_v1/event_selection.json').read_text())['events'];oldrows=[dict(event_id=e['event_id'],role='existing_simulated_event',window_start_jst=e['window_start_jst'],nine_hour_mm=e['reconstructed_rain_mm'],max_rolling_hour_mm=e['peak_rolling60min_reconstructed_mm'],chiyoda_mm=e['ward_mean_reconstructed_mm']['1'],chuo_mm=e['ward_mean_reconstructed_mm']['2'],minato_mm=e['ward_mean_reconstructed_mm']['3'],prior_rain_outside_window_mm=e['rain_before_window_reconstructed_mm'],hydraulic_result_available=True)for e in old];tab=pd.DataFrame(oldrows+new).sort_values('event_id');tab.to_csv(P/'five_event_rainfall_comparison.csv',index=False,encoding='utf-8-sig')
 fig,ax=plt.subplots(figsize=(9,4),constrained_layout=True);x=np.arange(len(tab));ax.bar(x-.18,tab.nine_hour_mm,.36,label='Nine-hour reconstructed rain');ax.bar(x+.18,tab.max_rolling_hour_mm,.36,label='Maximum rolling-hour reconstructed rain');ax.set_xticks(x,tab.event_id);ax.set_ylabel('Catchment-weighted rainfall (mm)');ax.legend();fig.savefig(R/'rainfall_comparison.png',dpi=160);plt.close(fig)
 fig,ax=plt.subplots(figsize=(9,4),constrained_layout=True)
 for j,k in enumerate(['chiyoda_mm','chuo_mm','minato_mm']):ax.bar(x+(j-1)*.24,tab[k],.24,label=k.replace('_mm','').title())
 ax.set_xticks(x,tab.event_id);ax.set_ylabel('Nine-hour ward-weighted reconstructed rain (mm)');ax.legend();fig.savefig(R/'ward_rainfall_comparison.png',dpi=160);plt.close(fig)
 checks['source_code_bound']=sha((ROOT/'src/preprocessing/acquire_population_additional_radar_v1.py').read_bytes())==json.loads((P/'protocol.json').read_text())['script_sha256'];assert all(checks.values()),checks;dump(R/'delivery_validation.json',dict(passed=True,checks=checks,unique_new_events=3,frames=864,new_hydraulics=False));dump(R/'summary.json',dict(new_events=new,existing_events=oldrows,new_hydraulics=False,recommendation='20240731 tests north-heavy spatial footprint;20250710 tests south-heavy convective footprint;20240618 tests prolonged rain with nonzero excluded antecedent rain. All require conservative forcing preparation and original numerical gates before hydraulics.'))
 body='<h1>新增历史暴雨数据：三场同规格雷达候选</h1><p>完成864帧原始数据下载、校验和绑定与时刻/雨量核验。均为JMA1km、5分钟代表强度产品，由京都大学RISH存档。按代表强度保持前300秒重建雨量，并非实测5分钟累计量。</p><p>只用研究汇水范围降雨选择每个完整JST日内最大9小时窗，未参考积水或交通影响。研究区69个有权重雷达格点无缺测、无饱和。没有运行新的水动力模拟。</p>'+tab.to_html(index=False,float_format=lambda v:f'{v:.2f}')+'<img src="rainfall_comparison.png"><img src="ward_rainfall_comparison.png"><h2>建议用途与边界</h2><p>2024-07-31在千代田明显偏强；2025-07-10在港区偏强，优先用作空间差异的外部情景。2024-06-18持续降雨较多，但选窗前还有约21.53mm汇水区平均降雨；若沿用干初态9小时配置，只能作受控对照，不能当完整历史洪水重建。应在补跑前明确前期湿润状态与时长。</p><p>先通过原保守空间雨量映射、屋面分配、水量体积和时钟接口，再沿用原数值准入；不同日期不自动等于独立随机样本。新事件尚无对应积水结果，不能接入人口影响数值。原措施保持固定，不能根据新雨场结果重新挑选保护道路。</p><p>原始数据与格式说明：<a href="http://database.rish.kyoto-u.ac.jp/arch/jmadata/">京都大学RISH的JMA数据档案</a>；'+ '；'.join('<a href="'+e['gauge_url']+'">'+e['date_jst']+'气象厅逐时观测</a>'for e in inv['events'])+'</p><p><a href="../../estimation/three_ward_night_population_transport_v1/review.html">返回人口接入结果</a></p>'
 style='body{font-family:system-ui,sans-serif;max-width:1100px;margin:30px auto;padding:0 18px;line-height:1.7;color:#233044}img{max-width:100%}table{border-collapse:collapse;font-size:12px;display:block;overflow-x:auto;max-width:100%}td,th{padding:7px;border:1px solid #ddd}'
 (R/'review.html').write_text('<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>新增三场历史雷达降雨资料</title><style>'+style+'</style>'+body+'</html>');print(tab.to_string(index=False));print('All radar delivery checks passed')
if __name__=='__main__':main()
